// Patio weather node: TMP36 logger with hold-to-freeze button.
// TMP36 on A0 (10 mV/°C + 500 mV), freeze button on D5, range lamp on D7.

const int TEMP_PIN = A0;
const int FREEZE_PIN = 5;
const int RANGE_PIN = 7;
const float MV_PER_C = 10.0f;
const float OFFSET_MV = 500.0f;
const float LOW_C = -10.0f;
const float HIGH_C = 50.0f;
const unsigned long PERIOD_MS = 1000;

unsigned long lastPrint = 0;
float tempC = 0.0f;
float frozenC = 0.0f;
bool freezeHeld = false;
unsigned long samples = 0;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float volts = raw * (5.0f / 1023.0f);
    return (volts - (OFFSET_MV / 1000.0f)) * 100.0f;
}

void updateRangeLamp(float c)
{
    bool ok = (c >= LOW_C) && (c <= HIGH_C);
    digitalWrite(RANGE_PIN, ok ? LOW : HIGH);
}

void printTemp(float c)
{
    Serial.print("Temp: ");
    Serial.println(c, 1);
}

void setup()
{
    pinMode(FREEZE_PIN, INPUT_PULLUP);
    pinMode(RANGE_PIN, OUTPUT);
    digitalWrite(RANGE_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
}

void loop()
{
    tempC = readTempC();
    samples++;
    freezeHeld = (digitalRead(FREEZE_PIN) == LOW);
    if (freezeHeld)
    {
        frozenC = tempC;
    }

    float report = freezeHeld ? frozenC : tempC;
    updateRangeLamp(report);

    unsigned long now = millis();
    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printTemp(report);
        Serial.print("weather n=");
        Serial.println(samples);
    }
}

// Loft cooling fan with hysteresis and a boost button.
// TMP-style linear probe on A3 (10 mV/°C), fan on D5, boost on D4.

const int TEMP_PIN = A3;
const int FAN_PIN = 5;
const int BOOST_PIN = 4;

const float ON_C = 36.0f;
const float OFF_C = 32.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long LOG_MS = 1000;
const unsigned long CONFIRM_MS = 200;
const unsigned long BOOST_CONFIRM_MS = 200;

bool fanOn = false;
bool onActive = false;
bool offActive = false;
unsigned long onSince = 0;
unsigned long offSince = 0;
bool boostRaw = false;
bool boostStable = false;
unsigned long boostSince = 0;
unsigned long lastSample = 0;
unsigned long lastLog = 0;
float tempC = 0.0f;

float sampleTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void driveFan(bool on)
{
    if (on == fanOn)
    {
        return;
    }
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void logLine()
{
    Serial.print("loft: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(BOOST_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastLog = millis();
    boostSince = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        tempC = sampleTempC();

        bool raw = (digitalRead(BOOST_PIN) == LOW);
        if (raw != boostRaw)
        {
            boostRaw = raw;
            boostSince = now;
        }
        if (now - boostSince >= BOOST_CONFIRM_MS)
        {
            boostStable = boostRaw;
        }

        if (boostStable)
        {
            onActive = false;
            offActive = false;
            driveFan(true);
        }
        else
        {
            if (tempC >= ON_C)
            {
                if (!onActive)
                {
                    onActive = true;
                    onSince = now;
                }
            }
            else
            {
                onActive = false;
            }
            if (tempC <= OFF_C)
            {
                if (!offActive)
                {
                    offActive = true;
                    offSince = now;
                }
            }
            else
            {
                offActive = false;
            }

            if (onActive && now - onSince >= CONFIRM_MS)
            {
                driveFan(true);
            }
            else if (offActive && now - offSince >= CONFIRM_MS)
            {
                driveFan(false);
            }
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        logLine();
    }
}

// Attic ridge-vent controller for an Uno.
// LM35 on A0, relay driver on D8, momentary override on D3 (pull-up).

const int TEMP_PIN = A0;
const int FAN_PIN = 8;
const int OVERRIDE_PIN = 3;

const float FAN_ON_C = 42.0f;
const float FAN_OFF_C = 38.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 300;

bool fanRunning = false;
bool pendingState = false;
bool havePending = false;
unsigned long pendingSinceMs = 0;
unsigned long lastSampleMs = 0;
unsigned long lastStatusMs = 0;
float lastTempC = 0.0f;

float readAtticTempC()
{
    int raw = analogRead(TEMP_PIN);
    float millivolts = raw * (5000.0f / 1023.0f);
    return millivolts / MV_PER_C;
}

void applyFan(bool wantOn)
{
    fanRunning = wantOn;
    digitalWrite(FAN_PIN, wantOn ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("attic: ");
    Serial.print(lastTempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanRunning ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(OVERRIDE_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSampleMs = millis();
    lastStatusMs = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSampleMs >= SAMPLE_MS)
    {
        lastSampleMs = now;
        lastTempC = readAtticTempC();

        bool overrideHeld = (digitalRead(OVERRIDE_PIN) == LOW);
        bool wantOn;
        if (overrideHeld)
        {
            wantOn = true;
        }
        else if (lastTempC >= FAN_ON_C)
        {
            wantOn = true;
        }
        else if (lastTempC <= FAN_OFF_C)
        {
            wantOn = false;
        }
        else
        {
            // Inside the hysteresis band: hold the current state.
            wantOn = fanRunning;
        }

        // Require the new state to hold continuously before accepting it.
        if (wantOn == fanRunning)
        {
            havePending = false;
        }
        else if (!havePending || pendingState != wantOn)
        {
            pendingState = wantOn;
            pendingSinceMs = now;
            havePending = true;
        }
        else if (now - pendingSinceMs >= CONFIRM_MS)
        {
            applyFan(wantOn);
            havePending = false;
        }
    }

    if (now - lastStatusMs >= STATUS_MS)
    {
        lastStatusMs = now;
        publishStatus();
    }
}

// Basement sump controller.
// Ultrasonic level proxy as linear voltage on A1, pump contactor on D7,
// silence button on D4 (active LOW, pull-up).

const uint8_t LEVEL_PIN = A1;
const uint8_t PUMP_PIN = 7;
const uint8_t SILENCE_PIN = 4;

const float START_CM = 45.0f;
const float STOP_CM = 30.0f;
const float MV_PER_CM = 10.0f;
const unsigned long POLL_MS = 40;
const unsigned long LOG_MS = 800;
const unsigned long CONFIRM_MS = 400;

bool pumpOn = false;
bool silenceLatched = false;
unsigned long lastPoll = 0;
unsigned long lastLog = 0;
float levelCm = 0.0f;

bool pendingValid = false;
bool pendingState = false;
unsigned long pendingSince = 0;

float sampleLevelCm()
{
    int adc = analogRead(LEVEL_PIN);
    float mv = adc * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void setPump(bool on)
{
    pumpOn = on;
    digitalWrite(PUMP_PIN, on ? HIGH : LOW);
}

void emitLog()
{
    Serial.print("sump cm=");
    Serial.print(levelCm, 1);
    Serial.print(" pump=");
    Serial.print(pumpOn ? 1 : 0);
    Serial.print(" mute=");
    Serial.println(silenceLatched ? 1 : 0);
}

void setup()
{
    pinMode(PUMP_PIN, OUTPUT);
    pinMode(SILENCE_PIN, INPUT_PULLUP);
    digitalWrite(PUMP_PIN, LOW);
    Serial.begin(9600);
    lastPoll = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long t = millis();

    if (digitalRead(SILENCE_PIN) == LOW)
    {
        silenceLatched = true;
        setPump(false);
    }

    if (t - lastPoll >= POLL_MS)
    {
        lastPoll = t;
        levelCm = sampleLevelCm();

        if (!silenceLatched)
        {
            // Hysteresis band: start at 45 cm, stop at 30 cm.
            bool want = pumpOn;
            if (!pumpOn && levelCm >= START_CM)
            {
                want = true;
            }
            else if (pumpOn && levelCm <= STOP_CM)
            {
                want = false;
            }

            if (want != pumpOn)
            {
                // Require the new state to hold continuously before switching.
                if (!pendingValid || pendingState != want)
                {
                    pendingValid = true;
                    pendingState = want;
                    pendingSince = t;
                }
                else if (t - pendingSince >= CONFIRM_MS)
                {
                    setPump(want);
                    pendingValid = false;
                }
            }
            else
            {
                pendingValid = false;
            }
        }
        else
        {
            pendingValid = false;
        }
    }

    if (t - lastLog >= LOG_MS)
    {
        lastLog = t;
        emitLog();
    }
}

// Foyer wall switch: one pushbutton toggles a lamp channel.
// Button D5 to ground (pull-up), lamp driver D11, status over serial.

const int SWITCH_PIN = 5;
const int LAMP_PIN = 11;
const unsigned long STATUS_EVERY_MS = 1500;
const unsigned long SETTLE_MS = 40;

bool lampLit = false;
int previousRaw = HIGH;
int settledRaw = HIGH;
int candidateRaw = HIGH;
unsigned long candidateSince = 0;
unsigned long lastStatusAt = 0;
unsigned long pressEvents = 0;
unsigned long bootMs = 0;

void driveLamp(bool on)
{
    lampLit = on;
    digitalWrite(LAMP_PIN, on ? HIGH : LOW);
}

void flipLamp()
{
    driveLamp(!lampLit);
    pressEvents++;
}

bool isPressedEdge(int previous, int current)
{
    return previous == HIGH && current == LOW;
}

void reportLamp()
{
    Serial.print("foyer lamp=");
    Serial.println(lampLit ? "ON" : "OFF");
}

void setup()
{
    pinMode(SWITCH_PIN, INPUT_PULLUP);
    pinMode(LAMP_PIN, OUTPUT);
    driveLamp(false);
    Serial.begin(9600);
    previousRaw = digitalRead(SWITCH_PIN);
    settledRaw = previousRaw;
    candidateRaw = previousRaw;
    candidateSince = millis();
    lastStatusAt = millis();
    bootMs = millis();
}

void loop()
{
    int raw = digitalRead(SWITCH_PIN);
    unsigned long now = millis();

    if (raw != candidateRaw)
    {
        candidateRaw = raw;
        candidateSince = now;
    }
    else if (candidateRaw != settledRaw && now - candidateSince >= SETTLE_MS)
    {
        settledRaw = candidateRaw;
        if (isPressedEdge(previousRaw, settledRaw))
        {
            flipLamp();
        }
        previousRaw = settledRaw;
    }

    if (now - lastStatusAt >= STATUS_EVERY_MS)
    {
        lastStatusAt = now;
        reportLamp();
    }
}

// Greenhouse ridge-vent controller.
// Soil-air LM35 on A2, exhaust fan relay on D9, UART status.

const int SENSOR_PIN = A2;
const int FAN_PIN = 9;
const float OPEN_C = 28.0f;
const float CLOSE_C = 24.0f;
const float FAULT_LOW_C = 5.0f;
const float FAULT_HIGH_C = 100.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 300;

bool fanOn = false;
bool pendingOn = false;
bool havePending = false;
unsigned long pendingSince = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
unsigned long sampleCount = 0;
float tempC = 0.0f;
float tempMin = 999.0f;
float tempMax = -999.0f;

float readTempC()
{
    int raw = analogRead(SENSOR_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void trackTemp(float c)
{
    if (c < tempMin)
    {
        tempMin = c;
    }
    if (c > tempMax)
    {
        tempMax = c;
    }
}

void setFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("gh: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        sampleCount++;
        trackTemp(tempC);

        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);
        bool wantOn;

        if (fault)
        {
            wantOn = true;
        }
        else if (fanOn)
        {
            wantOn = !(tempC <= CLOSE_C);
        }
        else
        {
            wantOn = (tempC >= OPEN_C);
        }

        if (wantOn == fanOn)
        {
            havePending = false;
        }
        else if (!havePending || pendingOn != wantOn)
        {
            havePending = true;
            pendingOn = wantOn;
            pendingSince = now;
        }
        else if (now - pendingSince >= CONFIRM_MS)
        {
            setFan(wantOn);
            havePending = false;
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Control-panel key: toggles a status LED for the technician.
// Key on D2 (pull-up to Vcc, closes to ground), LED on D13.

const int KEY_PIN = 2;
const int LED_PIN = 13;
const unsigned long REPORT_MS = 1000;
const unsigned long SETTLE_MS = 40;

bool ledLit = false;
int previous = HIGH;
unsigned long lastReport = 0;
unsigned long edgeCount = 0;
unsigned long bootMs = 0;

int stableLevel = HIGH;
unsigned long stableSince = 0;

void writeLed(bool on)
{
    ledLit = on;
    digitalWrite(LED_PIN, on ? HIGH : LOW);
}

void flipLed()
{
    writeLed(!ledLit);
    edgeCount++;
}

bool fallingEdge(int previousLevel, int currentLevel)
{
    return previousLevel == HIGH && currentLevel == LOW;
}

void report()
{
    Serial.print("panel led=");
    Serial.print(ledLit ? 1 : 0);
    Serial.print(" edges=");
    Serial.println(edgeCount);
}

void setup()
{
    pinMode(KEY_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    writeLed(false);
    Serial.begin(9600);
    previous = digitalRead(KEY_PIN);
    stableLevel = previous;
    stableSince = millis();
    lastReport = millis();
    bootMs = millis();
}

void loop()
{
    int nowLevel = digitalRead(KEY_PIN);
    unsigned long t = millis();

    if (nowLevel != stableLevel)
    {
        stableLevel = nowLevel;
        stableSince = t;
    }
    else if (t - stableSince >= SETTLE_MS)
    {
        if (fallingEdge(previous, stableLevel))
        {
            flipLed();
        }
        previous = stableLevel;
    }

    if (t - lastReport >= REPORT_MS)
    {
        lastReport = t;
        report();
    }
}

// Shop bench run/stop: mushroom estop toggles the "machine armed" lamp.
// Estop contact on D6 (NC to ground via switch, pull-up), armed lamp on D9.

const uint8_t ESTOP_PIN = 6;
const uint8_t ARMED_PIN = 9;
const unsigned long BEAT_MS = 1200;
const unsigned long SETTLE_MS = 50;

bool armed = false;
uint8_t priorSample = HIGH;
uint8_t stableSample = HIGH;
uint8_t candidateSample = HIGH;
unsigned long candidateSince = 0;
unsigned long lastBeat = 0;
unsigned long pressCount = 0;
unsigned long bootMs = 0;

void writeArmed(bool level)
{
    armed = level;
    digitalWrite(ARMED_PIN, level ? HIGH : LOW);
}

void toggleArmed()
{
    writeArmed(!armed);
    pressCount++;
}

bool fallingEdge(uint8_t previous, uint8_t current)
{
    return previous == HIGH && current == LOW;
}

void heartbeat()
{
    Serial.print("shop armed=");
    Serial.print(armed ? 1 : 0);
    Serial.print(" presses=");
    Serial.println(pressCount);
}

void setup()
{
    pinMode(ESTOP_PIN, INPUT_PULLUP);
    pinMode(ARMED_PIN, OUTPUT);
    writeArmed(false);
    Serial.begin(9600);
    priorSample = digitalRead(ESTOP_PIN);
    stableSample = priorSample;
    candidateSample = priorSample;
    candidateSince = millis();
    lastBeat = millis();
    bootMs = millis();
}

void loop()
{
    uint8_t sample = digitalRead(ESTOP_PIN);
    unsigned long now = millis();

    if (sample != candidateSample)
    {
        candidateSample = sample;
        candidateSince = now;
    }
    else if (candidateSample != stableSample && now - candidateSince >= SETTLE_MS)
    {
        stableSample = candidateSample;
        if (fallingEdge(priorSample, stableSample))
        {
            toggleArmed();
        }
        priorSample = stableSample;
    }

    if (now - lastBeat >= BEAT_MS)
    {
        lastBeat = now;
        heartbeat();
    }
}
